CH = dict(num=16, tag="Political Science · Ch 4", theme="Functions, types and party systems, national and state parties, challenges and reforms",
 title="Political Parties",
 intro="Political parties are the most visible institutions in a democracy and the ones people trust least. This chapter explains what a party is, its functions, how party systems differ, which parties are national and state parties in India, what challenges they face and how they can be reformed.",
 big_questions=["Why do we need political parties?", "How many parties are good for a democracy?", "Which parties are national or state parties?", "What are their challenges and reforms?"],
 blocks=[
 ("h2", "Meaning and Functions"),
 ("note", "DEFINITION", "A **political party** is a group of people who come together to contest elections and hold power in the government. They agree on some policies and programmes for the society with a view to promoting the collective good."),
 ("p", "A party has three components: **leaders, active members and followers**. It reflects fundamental political divisions in a society; parties are about a part of the society and thus **partisan**."),
 ("table", ["Function", "What the party does"], [["Contest elections", "Candidates are put up by parties; in India, usually chosen by top party leaders; in the USA, by members and supporters"], ["Put forward policies and programmes", "Voters choose from them; parties group issues and propose them as programmes"], ["Make laws", "Laws are debated and passed in the legislature; most members belong to a party and follow its direction"], ["Form and run governments", "Executives are selected from the ruling party; the party gives policy direction"], ["Play the role of opposition", "Parties that lose elections criticise the government, mobilise opposition and voice views"], ["Shape public opinion", "Raise issues and launch movements; many pressure groups are offshoots of parties"], ["Provide access to government machinery and welfare schemes", "Local party workers act as a link between people and the government"]]),
 ("p", "**Necessity:** Without parties, every candidate in elections would be independent; no one could make any promises to the people about major policies, and the government would be formed without a clear direction. A modern democracy needs parties as representative democracy works at a large scale, with different views to be brought together."),
 ("h2", "Party Systems"),
 ("table", ["System", "Description", "Examples"], [["One-party", "Only one party is allowed to control and run the government", "China (Communist Party)"], ["Two-party", "Power usually changes between two main parties; others win few seats", "USA, UK"], ["Multi-party", "Several parties compete for power; coalition governments; in India, parties form **alliances**, such as the National Democratic Alliance, the United Progressive Alliance and the Left Front in the 2004 Lok Sabha elections", "India"]]),
 ("p", "No system is ideal for all countries; India's multi-party system suits its social and geographical diversity. It may look messy and lead to political instability, but it allows a variety of interests and opinions to enjoy political representation."),
 ("h2", "National and State Parties"),
 ("ul", ["The **Election Commission of India** registers parties and gives them recognition as a national or state party. A **recognised party** is given a symbol and facilities.", "A party that secures at least **6 per cent of the total votes in Lok Sabha or assembly elections in four states and wins at least four seats in the Lok Sabha** is a **national party**; alternatively, 2 per cent of Lok Sabha seats from at least three states, or recognition as a state party in four states.", "A party that secures at least **6 per cent of votes in an assembly election and wins at least two seats** is recognised as a **state party** (alternatively, 3 per cent of seats or three seats)."]),
 ("table", ["National party", "Founded", "Key ideas"], [["Indian National Congress (INC)", "1885", "One of the oldest parties; secularism, welfare and liberal democracy; formed governments for most years after independence"], ["Bharatiya Janata Party (BJP)", "1980", "Cultural nationalism and integral humanism; a stated aim of a uniform civil code; earlier limited to the north, west and urban areas, its support spread to the south, east, north-east and rural areas from the 1990s"], ["Bahujan Samaj Party (BSP)", "1984, Kanshi Ram", "Represents Bahujan samaj (dalits, adivasis, OBCs, religious minorities); social justice"], ["Communist Party of India (Marxist) (CPI-M)", "1964", "Marxism-Leninism, secularism and democracy; supports socialism, opposes imperialism and communalism; strong in Kerala, West Bengal, Tripura"], ["National People's Party (NPP)", "2013", "Recognised as a national party in 2019 from Meghalaya, in the North-east"], ["Aam Aadmi Party (AAP)", "2012", "Anti-corruption, clean politics; given national status in 2023"]]),
 ("note", "NOTE", "National party status is reviewed after elections by the Election Commission, so the list changes. The list above is as per the Commission's recognitions of 2023; check the latest Commission notification. Parties such as the Trinamool Congress, NCP and CPI lost national status in 2023."),
 ("ul", ["**State parties** are those recognised in a state, e.g. Samajwadi Party, RJD, DMK, AIADMK, BJD, Shiv Sena, TDP; some started as regional parties and later expanded; the number of state parties has increased and they play an important role in coalition governments.", "Regional parties have grown in number and strength; no single national party won a majority in the Lok Sabha until 2014, so national parties had to form alliances with state parties, and since 1996 nearly every state party has been part of some coalition government at the Centre."]),
 ("h2", "Challenges to Political Parties"),
 ("ol", ["**Lack of internal democracy:** all over the world there is a tendency in parties towards the concentration of power in one or a few leaders at the top. Parties do not keep membership registers, do not hold organisational meetings and do not conduct internal elections.", "**Dynastic succession:** most political parties do not practise open and transparent procedures for their functioning; ordinary members have little information and little influence; leaders favour relatives, which is unfair to ordinary members and undermines democracy.", "**Growing role of money and muscle power:** parties tend to nominate candidates who can raise money and win; rich people and companies exert influence; criminals have been in politics.", "**Meaningful choice to voters:** parties do not offer much choice, as there are no big differences in policies; in some cases, leaders switch parties."]),
 ("h2", "How Can Parties Be Reformed?"),
 ("ul", ["**Anti-defection law:** The Constitution was amended (**52nd Amendment, 1985**; strengthened by the **91st Amendment, 2003**) to prevent elected MPs and MLAs from changing parties; defectors lose their seats.", "**Supreme Court order:** every candidate has to file an affidavit giving details of his or her property and criminal cases pending; the **Election Commission** made it compulsory for parties to hold organisational elections and file income tax returns.", "Suggested reforms: a law to regulate internal affairs; reservation of one-third tickets for women; **State funding** of elections to reduce use of money; and **people's pressure** through petitions, publicity and agitations; also, ordinary citizens can improve parties by joining them."]),
 ("h2", "Quick Revision: Likely Exam Questions"),
 ("qa", [
  ("Define a political party.", "Group of people who come together to contest elections and hold power for collective good."),
  ("Name three functions of parties.", "Contest elections, form governments, act as opposition."),
  ("What is a multi-party system?", "Several parties compete and may share power, e.g. India."),
  ("Who recognises national and state parties?", "Election Commission of India."),
  ("What is the anti-defection law?", "Law disqualifying legislators who defect after being elected."),
  ("Name two challenges to parties.", "Lack of internal democracy and role of money and muscle power."),
  ("Suggest one reform.", "State funding of elections or compulsory internal elections."),
 ]),
 ],
 takeaways=["Parties contest elections, form governments, play the opposition and shape public opinion.", "India has a **multi-party system** with alliances; ECI recognises **national and state parties**.", "Main challenges: **lack of internal democracy, dynastic succession, money and muscle power, lack of real choice**.", "Reforms include the **anti-defection law (1985, 2003)**, affidavits and compulsory income tax returns.", "Pressure from citizens, and citizens joining parties, can push parties to reform."])
